			/**
			 * 게시판을 등록할 프로그램 정보를 셋팅합니다.
			 */
			function updateProgramInfo() {
			    
			    var voDsEndPoint = app.lookup("dsEndPoints");
			    var vsBrdType = app.lookup("rdbBrdType").value;
			    var vsUrlAddr;
			    
			    if (vsBrdType == 1) { // 일반게시판(공지)
			        vsUrlAddr = msDefaultBrdUrl;
			    } else if (vsBrdType == 2) { // 답글 게시판
			        vsUrlAddr = msReplyBrdUrl;
			    } else { // 댓글 게시판
			        vsUrlAddr = msCommentBrdUrl;
			    }
			    
			    //insert
			    if (ValueUtil.isNull(msBrdId)) {
			        
			        var vsCmbPgmVal = app.lookup("cmbProgramCode").value;
			        var vsUntSysSeCd = app.lookup("dsCmbUntTaskwkSeCd").findFirstRow("CMMNS_CD_VALUE == '" + vsCmbPgmVal + "'").getValue("SYS_MENU_NO");
			        
			        var voRowData = {
			            UNT_SYS_SE_CD: vsUntSysSeCd,
			            PROGRM_NM: app.lookup("ipbBrdNm").value,
			            OUTSD_PROGRM_YN: "N",
			            URL_ADDR: vsUrlAddr,
			            PROGRM_USE_SE_CD: "1"
			        }
			        voDsEndPoint.insertRowData(0, true, voRowData);
			        
			    } else { //update
			        voDsEndPoint.setValue(0, "UNT_SYS_SE_CD", app.lookup("cmbProgramCode").value);
			        voDsEndPoint.setValue(0, "PROGRM_NM", app.lookup("ipbBrdNm").value);
			        voDsEndPoint.setValue(0, "OUTSD_PROGRM_YN", "N");
			        voDsEndPoint.setValue(0, "URL_ADDR", vsUrlAddr);
			        voDsEndPoint.setValue(0, "PROGRM_USE_SE_CD", "1");
			        voDsEndPoint.setValue(0, "RM_CN", "BOARD_ID_" + msBrdId);
			    }
			}

