			//************************** 상세 설정 Function **************************/

			/**
			 * 상세설정, 답글설정, 목록설정을 초기값으로 변경한다.
			 */
			function resetBoardContents() {
			    
			    // 조회수 표시 여부
			    var vbRdcntYn = util.Grid.getCellValue(app, "grdBoardList", "RDCNT_INDCT_YN");
			    
			    /* 상세 프리폼 초기화 */
			    resetBoardFreeForm("grpBoardDtl", vbRdcntYn);
			    
			    if (msSelectBrdType == "2") {
			        /* 답글 설정 프리폼 초기화 */
			        resetBoardFreeForm("grpBoardReply", vbRdcntYn);
			    }
			    
			    /* 목록설정 그리드 초기화 */
			    var vcGrdBoardList = app.lookup("grdInsertBoardList");
			    
			    vcGrdBoardList.header.getCellIndices().forEach(function(idx) {
			        
			        if (maDefGrdCellIdx.indexOf(idx) == -1) {
			            vcGrdBoardList.deleteColumn(idx);
			        }
			        
			    });
			    
			    /* 목록설정 그리드 조회수 표시 */
			    if (vbRdcntYn == "Y") {
			        vcGrdBoardList.columnVisible(5, true);
			    } else {
			        vcGrdBoardList.columnVisible(5, false);
			    }
			    
			    /* 목록설정 컬럼 버튼영역 초기화 */
			    var vcGrpListCol = app.lookup("grpListCol");
			    vcGrpListCol.removeAllChildren();
			}

			/**
			 * 게시판 내부 입력 프리폼에 대한 설정을 초기화합니다.(상세설정, 답글설정)
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 초기화 그룹 ID
			 * @param {String} psRdcntYn 조회조건 사용여부("Y")
			 */
			function resetBoardFreeForm(psGrpId, psRdcntYn) {
			    
			    /* 입력 프리폼 초기화 */
			    var vcGrpBrdForm = app.lookup(psGrpId);
			    var voGrpBoardDtlLot = vcGrpBrdForm.getLayout();
			    var vaGrpDtlRows = voGrpBoardDtlLot.getRows();
			    
			    showBoardFormRdcnt(psGrpId, psRdcntYn);
			    
			    /* 로우수 초기화 */
			    if (vaGrpDtlRows.length > 5) {
			        
			        var vaRemoveRows = [];
			        for (var i = 2; i <= vaGrpDtlRows.length - 4; i++) {
			            vaRemoveRows.push(i);
			        }
			        voGrpBoardDtlLot.removeRows(vaRemoveRows);
			    }
			    
			    /* 내부 입력조건 행, 컬럼 갯수 초기화 */
			    if (psGrpId == "grpBoardDtl") {
			        util.Control.setValue(app, "nbeDtlColCnt", 1);
			        util.Control.setValue(app, "nbeDtlRowCnt", 1);
			    } else {
			        util.Control.setValue(app, "nbeReplyColCnt", 1);
			        util.Control.setValue(app, "nbeReplyRowCnt", 1);
			    }
			}

			/**
			 * 상세설정 목록의 로우를 추가합니다.
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 설정그룹 ID(상세, 답글)
			 * @param {Number} pnRowCnt 로우 Count
			 * @param {Number} pnColCnt 컬럼 Count
			 * @param {Array} paColIdx 컬럼 index 배열
			 */
			function addFreeFormRow(psGrpId, pnRowCnt, pnColCnt, paColIdx) {
			    
			    /**@type cpr.controls.Container*/
			    var vcGrpBrdForm = app.lookup(psGrpId);
			    /**@type cpr.controls.layouts.FormLayout*/
			    var voGrpBrdLot = vcGrpBrdForm.getLayout();
			    var vaRows = voGrpBrdLot.getRows();
			    var vaChildCtrl = vcGrpBrdForm.getChildren();
			    var vnLastColIdx;
			    
			    var vnRowCnt = vaRows.length;
			    
			    if (vnRowCnt >= 11) {
			        util.Msg.alert(app, "추가 행은 최대 6개까지 가능합니다.");
			        return false;
			    } else if (vnRowCnt + pnRowCnt > 11) {
			        pnRowCnt = 11 - vnRowCnt;
			    }
			    
			    // row 추가    
			    for (var i = 0; i < pnRowCnt; i++) {
			        vaRows.unshift("25px");
			    }
			    voGrpBrdLot.setRows(vaRows);
			    
			    // row 추가에 따른 기본 컨트롤 항목이동       
			    vaChildCtrl.forEach(function(ctrl) {
			        var voCons = vcGrpBrdForm.getConstraint(ctrl);
			        if (voCons.rowIndex == 0 || voCons.rowIndex == 1) return;
			        
			        voCons.rowIndex += pnRowCnt;
			        vcGrpBrdForm.replaceConstraint(ctrl, voCons);
			    });
			    
			    //TODO 공지유형 라인 숨김처리
			    voGrpBrdLot.setRowVisible(1, false);
			    
			    var vnCmbColBatVal = null;
			    
			    // 추가 동작이면 콤보 value로 값을 적용하고 draw 작업에서는 구분처리한다
			    if (ValueUtil.isNull(paColIdx)) {
			        if (psGrpId == "grpBoardDtl") {
			            vnCmbColBatVal = app.lookup("cmbDtlColBat").value;
			        } else {
			            vnCmbColBatVal = app.lookup("cmbReplyColBat").value;
			        }
			        
			    } else {
			        var vnColCnt = paColIdx.length;
			        var vsJStringColIdx = JSON.stringify(paColIdx);
			        
			        if (paColIdx.length == 2) {
			            if (vsJStringColIdx === JSON.stringify([1, 3])) {
			                vnCmbColBatVal = 2;
			            } else if (vsJStringColIdx === JSON.stringify([1, 5])) {
			                vnCmbColBatVal = 3;
			            } else if (vsJStringColIdx === JSON.stringify([1, 7])) {
			                vnCmbColBatVal = 4;
			            }
			        } else if (paColIdx.length == 3) {
			            if (vsJStringColIdx === JSON.stringify([1, 3, 5])) {
			                vnCmbColBatVal = 5;
			            } else if (vsJStringColIdx === JSON.stringify([1, 3, 7])) {
			                vnCmbColBatVal = 6;
			            } else if (vsJStringColIdx === JSON.stringify([1, 5, 7])) {
			                vnCmbColBatVal = 7;
			            }
			        }
			    }
			    
			    // 추가된 row에 컨트롤 삽입
			    for (var i = 1; i <= pnRowCnt; i++) {
			        for (var j = 0; j < pnColCnt; j++) {
			            
			            var voCtrlConst = {
			                rowIndex: i + 1,
			                rowSpan: 1
			            };
			            
			            if (pnColCnt == 1) {
			                voCtrlConst["colIndex"] = j + 1;
			                voCtrlConst["colSpan"] = 7;
			                vnLastColIdx = 1;
			            } else if (pnColCnt == 2) {
			                
			                if (vnCmbColBatVal == "2") { // 1-3
			                    if (j == 0) {
			                        voCtrlConst["colIndex"] = 1;
			                        voCtrlConst["colSpan"] = 1;
			                    } else {
			                        voCtrlConst["colIndex"] = 3;
			                        voCtrlConst["colSpan"] = 5;
			                    }
			                    vnLastColIdx = 3;
			                } else if (vnCmbColBatVal == "3") { // 2-2
			                    if (j == 0) {
			                        voCtrlConst["colIndex"] = 1;
			                        voCtrlConst["colSpan"] = 3;
			                    } else {
			                        voCtrlConst["colIndex"] = 5;
			                        voCtrlConst["colSpan"] = 3;
			                    }
			                    vnLastColIdx = 5;
			                } else if (vnCmbColBatVal == "4") { // 3-1
			                    if (j == 0) {
			                        voCtrlConst["colIndex"] = 1;
			                        voCtrlConst["colSpan"] = 5;
			                    } else {
			                        voCtrlConst["colIndex"] = 7;
			                        voCtrlConst["colSpan"] = 1;
			                    }
			                    vnLastColIdx = 7;
			                }
			                
			            } else if (pnColCnt == 3) {
			                if (vnCmbColBatVal == "5") { // 1-1-2
			                    if (j == 0) {
			                        voCtrlConst["colIndex"] = 1;
			                        voCtrlConst["colSpan"] = 1;
			                    } else if (j == 1) {
			                        voCtrlConst["colIndex"] = 3;
			                        voCtrlConst["colSpan"] = 1;
			                    } else {
			                        voCtrlConst["colIndex"] = 5;
			                        voCtrlConst["colSpan"] = 3;
			                    }
			                    vnLastColIdx = 5;
			                } else if (vnCmbColBatVal == "6") { // 1-2-1
			                    if (j == 0) {
			                        voCtrlConst["colIndex"] = 1;
			                        voCtrlConst["colSpan"] = 1;
			                    } else if (j == 1) {
			                        voCtrlConst["colIndex"] = 3;
			                        voCtrlConst["colSpan"] = 3;
			                    } else {
			                        voCtrlConst["colIndex"] = 7;
			                        voCtrlConst["colSpan"] = 1;
			                    }
			                    vnLastColIdx = 7;
			                } else if (vnCmbColBatVal == "7") { // 2-1-1
			                    if (j == 0) {
			                        voCtrlConst["colIndex"] = 1;
			                        voCtrlConst["colSpan"] = 3;
			                    } else if (j == 1) {
			                        voCtrlConst["colIndex"] = 5;
			                        voCtrlConst["colSpan"] = 1;
			                    } else {
			                        voCtrlConst["colIndex"] = 7;
			                        voCtrlConst["colSpan"] = 1;
			                    }
			                    vnLastColIdx = 7;
			                }
			                
			            } else {
			                voCtrlConst["colIndex"] = (j * 2) + 1;
			                voCtrlConst["colSpan"] = 1;
			                vnLastColIdx = 7;
			            }
			            
			            var vcAddGroup = new cpr.controls.Container("_beforeGrp" + voCtrlConst["rowIndex"] + voCtrlConst["colIndex"]);
			            // Layout
			            var xYLayout_1 = new cpr.controls.layouts.XYLayout();
			            vcAddGroup.setLayout(xYLayout_1);
			            
			            if (voCtrlConst["colIndex"] == vnLastColIdx) {
			                (function(container) {
			                    var vcBtnAdd = createOptionButton(psGrpId, "ADD");
			                    container.addChild(vcBtnAdd, {
			                        "width": "22px",
			                        "height": "22px",
			                        "left": "calc(50% - 11px)",
			                        "top": "calc(50% - 11px)"
			                    });
			                    var vcBtnDel = createOptionButton(psGrpId, "DELETE");
			                    container.addChild(vcBtnDel, {
			                        "right": "59px",
			                        "width": "22px",
			                        "height": "22px",
			                        "top": "calc(50% - 11px)"
			                    });
			                    var vcBtnUp = createOptionButton(psGrpId, "UP");
			                    container.addChild(vcBtnUp, {
			                        "right": "32px",
			                        "width": "22px",
			                        "height": "22px",
			                        "top": "calc(50% - 11px)"
			                    });
			                    var vcBtnDown = createOptionButton(psGrpId, "DOWN");
			                    container.addChild(vcBtnDown, {
			                        "right": "5px",
			                        "width": "22px",
			                        "height": "22px",
			                        "top": "calc(50% - 11px)"
			                    });
			                })(vcAddGroup);
			                
			            } else {
			                (function(container) {
			                    var vcBtnAdd = createOptionButton(psGrpId, "ADD");
			                    container.addChild(vcBtnAdd, {
			                        "width": "22px",
			                        "height": "22px",
			                        "left": "calc(50% - 11px)",
			                        "top": "calc(50% - 11px)"
			                    });
			                })(vcAddGroup);
			            }
			            
			            vcGrpBrdForm.addChild(vcAddGroup, voCtrlConst);
			        }
			    }
			}

			/**
			 * boardColList 정보로 상세, 답글, 댓글, 목록을 그린다.
			 */
			function drawBoardContents() {
			    
			    // 상세설정, 답글설정 초기화
			    resetBoardContents();
			    
			    if (app.lookup("dsBoardColList").getRowCount() == 0) return;
			    
			    /* 상세설정 그리기 */
			    drawBoardForm("grpBoardDtl");
			    
			    /* 답글설정 그리기 */
			    if (msSelectBrdType == "2") {
			        drawBoardForm("grpBoardReply");
			    }
			    
			    /* 목록설정 그리기*/
			    drawBoardList();
			}

			/**
			 * 게시판 상세, 답글 설정 그리기
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 초기화 그룹 ID
			 */
			function drawBoardForm(psGrpId) {
			    
			    var voDsBrdColList = app.lookup("dsBoardColList");
			    
			    // 상세, 답글상세의 경우 게시판 템플릿 구분코드로 구분
			    if (psGrpId == "grpBoardDtl") {
			        voDsBrdColList.setFilter("NTABRD_TMPT_SE_CD == 1");
			    } else {
			        voDsBrdColList.setFilter("NTABRD_TMPT_SE_CD == 2");
			    }
			    
			    var vaDsBrdColDatas = voDsBrdColList.getRowDataRanged();
			    
			    if (vaDsBrdColDatas.length == 0) return;
			    
			    var vaRowIdx = [];
			    var voColIdx = {};
			    
			    vaDsBrdColDatas.forEach(function(rowData) {
			        var voColConst = JSON.parse(rowData["COL_PLACEM_INFO_CN"]);
			        var vnRowIdx = voColConst["rowIndex"];
			        var vnColIdx = voColConst["colIndex"];
			        
			        vaRowIdx.push(vnRowIdx);
			        
			        if (vnRowIdx in voColIdx) {
			            voColIdx[vnRowIdx].push(vnColIdx);
			        } else {
			            voColIdx[vnRowIdx] = [vnColIdx];
			        }
			        
			    });
			    
			    var maxRowIdx = vaRowIdx.reduce(function(a, b) {
			        return Math.max(a, b);
			    });
			    
			    for (var i = maxRowIdx; i > 1; i--) { // 로우가 2번 부터 생성됨      
			        var vnColCnt = voColIdx[i].length;
			        addFreeFormRow(psGrpId, 1, vnColCnt, voColIdx[i]);
			    }
			    
			    vaDsBrdColDatas.forEach(function(rowData) {
			        var voConst = JSON.parse(rowData["COL_PLACEM_INFO_CN"]);
			        
			        if (voConst["horizontalAlign"]) {
			            delete voConst.horizontalAlign;
			            delete voConst.width;
			        }
			        
			        createBoardCtrl(psGrpId, voConst, rowData);
			        
			    });
			}

			/**
			 * 게시판 목록설정 그리기
			 */
			function drawBoardList() {
			    
			    var voDsBrdColList = app.lookup("dsBoardColList");
			    //    voDsBrdColList.setFilter("NTABRD_TMPT_SE_CD == 1");
			    voDsBrdColList.clearFilter();
			    
			    var vaDsBrdColDatas = voDsBrdColList.getRowDataRanged();
			    
			    /* 목록설정 그리드 그리기 */
			    var vaListColInfo = [];
			    
			    vaDsBrdColDatas.forEach(function(rowData) {
			        
			        if (!ValueUtil.isNull(rowData["NTABRD_COL_SRTNG_SQNCE"])) {
			            var voListInfo = {};
			            voListInfo["NTABRD_COL_SRTNG_SQNCE"] = rowData["NTABRD_COL_SRTNG_SQNCE"];
			            voListInfo["LIST_CONTRO_SIZEA_SZ"] = rowData["LIST_CONTRO_SIZEA_SZ"];
			            voListInfo["NTABRD_COL_NM"] = rowData["NTABRD_COL_NM"];
			            voListInfo["NTABRD_COL_ESNTAL_ID"] = rowData["NTABRD_COL_ESNTAL_ID"];
			            
			            vaListColInfo.push(voListInfo);
			        }
			    });
			    
			    vaListColInfo.sort(function(a, b) {
			        return a["NTABRD_COL_SRTNG_SQNCE"] - b["NTABRD_COL_SRTNG_SQNCE"];
			    });
			    
			    vaListColInfo.forEach(function(info) {
			        addGridColumn(info["NTABRD_COL_ESNTAL_ID"], info["NTABRD_COL_NM"], info["LIST_CONTRO_SIZEA_SZ"]);
			    });
			    
			    // 목록 설정의 컬럼 set
			    setColList();
			}

			/**
			 * 조회수 표시 여부에 따른 상세 프리폼 적용
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 초기화 그룹 ID
			 * @param {String} psRdcntYn 조회수 표시 여부("Y")
			 */
			function showBoardFormRdcnt(psGrpId, psRdcntYn) {
			    
			    var vcGrpBrdForm = app.lookup(psGrpId);
			    var vcOptRdCnt = vcGrpBrdForm.getChild("vcOptRdCnt");
			    var vcOptRdCntVal = vcGrpBrdForm.getChild("optRdcntVal");
			    
			    var vcOptWriDtVal;
			    
			    if (psGrpId == "grpBoardDtl") {
			        var vcOptWriDtVal = app.lookup("optDtlWriDtVal");
			    } else {
			        var vcOptWriDtVal = app.lookup("optReplyWriDtVal");
			    }
			    
			    var voConst = {
			        rowIndex: 0,
			        rowSpan: 1,
			        colIndex: 5,
			        colSpan: 3
			    };
			    
			    if (psRdcntYn == "Y") { // 조회수 표시
			        
			        delete voConst.rowSpan;
			        delete voConst.colSpan;
			        
			        vcGrpBrdForm.replaceConstraint(vcOptWriDtVal, voConst);
			        
			        if (ValueUtil.isNull(vcOptRdCnt)) {
			            vcOptRdCnt = new cpr.controls.Output("vcOptRdCnt");
			            vcOptRdCnt.value = "조회수";
			            vcOptRdCnt.style.addClass("label");
			            
			            vcOptRdCntVal = new cpr.controls.Output("optRdcntVal");
			            vcOptRdCntVal.value = "0";
			            vcOptRdCntVal.fieldLabel = "조회수";
			            
			            vcGrpBrdForm.addChild(vcOptRdCnt, {
			                rowIndex: 0,
			                colIndex: 6
			            });
			            vcGrpBrdForm.addChild(vcOptRdCntVal, {
			                rowIndex: 0,
			                colIndex: 7
			            });
			        }
			        
			    } else { // 조회수 제거
			        if (!ValueUtil.isNull(vcOptRdCnt)) {
			            
			            vcGrpBrdForm.removeChild(vcOptRdCnt);
			            vcGrpBrdForm.removeChild(vcOptRdCntVal);
			        }
			        
			        vcGrpBrdForm.replaceConstraint(vcOptWriDtVal, voConst);
			        
			    }
			}

			/**
			 * 컬럼 추가시 적용될 컨트롤의 옵션 버튼 생성
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 그룹 ID
			 * @param {"ADD" | "DELETE" | "UP" | "DOWN"} psOptionBtnType 옵션 버튼 타입
			 * @return {cpr.controls.Button} 옵션 버튼
			 */
			function createOptionButton(psGrpId, psOptionBtnType) {
			    
			    var vcOptionBtn = new cpr.controls.Button("_btn" + psOptionBtnType);
			    vcOptionBtn.userData("parentGrpId", psGrpId); // 해당버튼의 상세,답글 설정인지 적용
			    
			    if (psOptionBtnType == "ADD") {
			        vcOptionBtn.fieldLabel = "항목추가";
			        vcOptionBtn.tooltip = "항목추가";
			        vcOptionBtn.value = "+";
			        vcOptionBtn.style.setClasses(["btn-outline-secondary", "rounded-circle"]);
			        if (typeof clickBtnAdd == "function") {
			            vcOptionBtn.addEventListener("click", clickBtnAdd);
			        }
			    } else if (psOptionBtnType == "DELETE") {
			        vcOptionBtn.fieldLabel = "행삭제";
			        vcOptionBtn.tooltip = "행삭제";
			        vcOptionBtn.value = "-";
			        vcOptionBtn.style.setClasses(["btn-outline-secondary", "rounded-circle"]);
			        vcOptionBtn.style.css({
			            "border-bottom-color": "#ff0000",
			            "color": "#ff0500",
			            "border-left-color": "#ff0000",
			            "border-top-color": "#ff0000",
			            "border-right-color": "#ff0000"
			        });
			        if (typeof clickBtnDel == "function") {
			            vcOptionBtn.addEventListener("click", clickBtnDel);
			        }
			    } else if (psOptionBtnType == "UP") {
			        vcOptionBtn.fieldLabel = "위로 행이동";
			        vcOptionBtn.tooltip = "위로 행이동";
			        vcOptionBtn.value = "▲";
			        vcOptionBtn.style.setClasses(["btn-outline-secondary", "rounded-circle"]);
			        if (typeof clickBtnUp == "function") {
			            vcOptionBtn.addEventListener("click", clickBtnUp);
			        }
			        vcOptionBtn.style.css({
			            "font-size": "12px",
			            "border-bottom-color": "#8a8a8a",
			            "color": "#8a8a8a",
			            "border-left-color": "#8a8a8a",
			            "border-top-color": "#8a8a8a",
			            "border-right-color": "#8a8a8a"
			        });
			    } else {
			        vcOptionBtn.fieldLabel = "아래로 행이동";
			        vcOptionBtn.tooltip = "아래로 행이동";
			        vcOptionBtn.value = "▼";
			        vcOptionBtn.style.setClasses(["btn-outline-secondary", "rounded-circle"]);
			        vcOptionBtn.style.css({
			            "font-size": "12px",
			            "border-bottom-color": "#8a8a8a",
			            "color": "#8a8a8a",
			            "border-left-color": "#8a8a8a",
			            "border-top-color": "#8a8a8a",
			            "border-right-color": "#8a8a8a"
			        });
			        if (typeof clickBtnDown == "function") {
			            vcOptionBtn.addEventListener("click", clickBtnDown);
			        }
			    }
			    
			    return vcOptionBtn;
			}

			/**
			 * 컨트롤 추가 버튼 클릭시 팝업 호출 동작
			 */
			function clickBtnAdd( /* cpr.events.CMouseEvent */ e) {
			    
			    /**@type cpr.controls.Button*/
			    var vcBtnAdd = e.control;
			    var vsGrpId = vcBtnAdd.userData("parentGrpId");
			    
			    var vcGrpForm = app.lookup(vsGrpId);
			    var voDsBrdCol = app.lookup("dsBoardColList");
			    voDsBrdCol.clearFilter();
			    
			    var vcTargetCtrl = vcBtnAdd.getParent();
			    
			    // 마지막 컬럼 일경우 XY레이아웃이 2중으로 구성되어있음
			    if (vcTargetCtrl.id == "_lastGrp") {
			        vcTargetCtrl = vcTargetCtrl.getParent();
			    }
			    
			    var voConts = vcGrpForm.getConstraint(vcTargetCtrl);
			    var vsColId = vcTargetCtrl.userAttr("_colId");
			    
			    var voInitValue = null;
			    
			    if (vsColId) voInitValue = voDsBrdCol.findFirstRow("NTABRD_COL_ESNTAL_ID == '" + vsColId + "'").getRowData();
			    
			    util.Dialog.open(app, "app/exam/demo/dyncBrd/dyncBrdPop/dyncBrdCtrlPop", "게시판 필드 설정", 700, 240, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        if (returnValue) {
			            if (ValueUtil.isNull(vsColId)) {
			                insertBoardCtrl(vsGrpId, voConts, returnValue);
			            } else {
			                updateBoardCtrl(vsGrpId, voConts, returnValue, vsColId);
			            }
			        }
			    }, voInitValue, {
			        headerMax: false
			    });
			}

			/**
			 * 로우 삭제 버튼 클릭 동작
			 */
			function clickBtnDel( /* cpr.events.CMouseEvent */ e) {
			    
			    /**@type cpr.controls.Button*/
			    var vcBtnDel = e.control;
			    var vsGrpId = vcBtnDel.userData("parentGrpId");
			    
			    var vcGrpForm = app.lookup(vsGrpId);
			    var vcTargetCtrl = vcBtnDel.getParent();
			    var voConts = vcGrpForm.getConstraint(vcTargetCtrl);
			    var vnDelRowIdx = voConts.rowIndex;
			    
			    var voDsBoardCol = app.lookup("dsBoardColList");
			    voDsBoardCol.clearFilter();
			    
			    // 삭제된 컬럼 정보 삭제
			    vcGrpForm.getChildren().forEach(function(ctrl) {
			        
			        var voChildConts = vcGrpForm.getConstraint(ctrl);
			        
			        if (voChildConts.rowIndex == vnDelRowIdx) {
			            var vnAttrColId = ctrl.userAttr("_colId");
			            var vsAttrInsYn = ctrl.userAttr("_insertYn");
			            if (!ValueUtil.isNull(vnAttrColId)) {
			                
			                console.log(vnAttrColId);
			                console.log(voDsBoardCol.getRowDataRanged());
			                var vnRowIdx = voDsBoardCol.findFirstRow("NTABRD_COL_ESNTAL_ID == '" + vnAttrColId + "'").getIndex();
			                
			                // 신규로 생성한 컨트롤이면 즉시 삭제
			                if (vsAttrInsYn == "Y") {
			                    voDsBoardCol.realDeleteRow(vnRowIdx);
			                } else {
			                    voDsBoardCol.deleteRow(vnRowIdx);
			                    
			                    // TODO 상세,답글 설정 적용필요
			                    // 상세 컬럼 삭제시 목록 그리드 컬럼 제거
			                    var vcGrdInsBrdList = app.lookup("grdInsertBoardList");
			                    var vaGrdHdrColIdxs = vcGrdInsBrdList.header.getCellIndices();
			                    var vnGrdHdrColLng = vaGrdHdrColIdxs.length;
			                    
			                    for (var i = 0; i < vnGrdHdrColLng; i++) {
			                        var voInfo = {};
			                        
			                        var voCol = vcGrdInsBrdList.detail.getColumn(vaGrdHdrColIdxs[i]);
			                        var vsColId = voCol.columnName;
			                        var vsCellIdx = voCol.cellIndex;
			                        
			                        if (vnAttrColId == vsColId) {
			                            vcGrdInsBrdList.deleteColumn(vsCellIdx);
			                        }
			                    }
			                }
			            }
			        }
			    });
			    
			    vcGrpForm.getLayout().removeRows([vnDelRowIdx]);
			    
			}

			/**
			 * 위로 행이동 버튼 동작
			 */
			function clickBtnUp( /* cpr.events.CMouseEvent */ e) {
			    
			    /**@type cpr.controls.Button*/
			    var vcBtnUp = e.control;
			    var vsGrpId = vcBtnUp.userData("parentGrpId");
			    
			    var vcGrpForm = app.lookup(vsGrpId);
			    var vcTargetCtrl = vcBtnUp.getParent();
			    var voConst = vcGrpForm.getConstraint(vcTargetCtrl);
			    var vnRowIdx = voConst.rowIndex;
			    
			    // 첫번째 행 위로 이동 불가
			    if (vnRowIdx == 2) return false;
			    
			    var vaCurrentRowChild = [];
			    var vaUpRowChild = [];
			    
			    vcGrpForm.getChildren().forEach(function(ctrl) {
			        
			        var voChildConst = vcGrpForm.getConstraint(ctrl);
			        var voChildInfo = {};
			        
			        if (voChildConst.rowIndex === vnRowIdx - 1) {
			            voChildInfo["colIndex"] = voChildConst["colIndex"];
			            voChildInfo["ctrl"] = ctrl;
			            voChildInfo["const"] = voChildConst;
			            
			            vaUpRowChild.push(voChildInfo);
			            
			        } else if (voChildConst.rowIndex === vnRowIdx) {
			            voChildInfo["colIndex"] = voChildConst["colIndex"];
			            voChildInfo["ctrl"] = ctrl;
			            voChildInfo["const"] = voChildConst;
			            
			            vaCurrentRowChild.push(voChildInfo);
			        }
			    });
			    
			    vaCurrentRowChild.forEach(function(ctrlInfo) {
			        var voCtrlConst = ctrlInfo["const"];
			        voCtrlConst["rowIndex"] = voCtrlConst["rowIndex"] - 1;
			        vcGrpForm.replaceConstraint(ctrlInfo["ctrl"], voCtrlConst);
			    });
			    
			    vaUpRowChild.forEach(function(ctrlInfo) {
			        var voCtrlConst = ctrlInfo["const"];
			        voCtrlConst["rowIndex"] = voCtrlConst["rowIndex"] + 1;
			        vcGrpForm.replaceConstraint(ctrlInfo["ctrl"], voCtrlConst);
			    });
			}

			/**
			 * 아래로 행이동 버튼 동작
			 */
			function clickBtnDown( /* cpr.events.CMouseEvent */ e) {
			    
			    /**@type cpr.controls.Button*/
			    var vcBtnUp = e.control;
			    var vsGrpId = vcBtnUp.userData("parentGrpId");
			    
			    var vcGrpForm = app.lookup(vsGrpId);
			    var vcTargetCtrl = vcBtnUp.getParent();
			    var voConts = vcGrpForm.getConstraint(vcTargetCtrl);
			    var vnRowIdx = voConts.rowIndex;
			    var vnLastRowIdx = vcGrpForm.getConstraint(app.lookup("optTitle")).rowIndex;
			    
			    // 내용 컨텐츠 아래로 이동불가
			    if (vnRowIdx == vnLastRowIdx - 1) return false;
			    
			    var vaCurrentRowChild = [];
			    var vaDownRowChild = [];
			    
			    vcGrpForm.getChildren().forEach(function(ctrl) {
			        
			        var voChildConst = vcGrpForm.getConstraint(ctrl);
			        var voChildInfo = {};
			        
			        if (voChildConst.rowIndex === vnRowIdx + 1) {
			            voChildInfo["colIndex"] = voChildConst["colIndex"];
			            voChildInfo["ctrl"] = ctrl;
			            voChildInfo["const"] = voChildConst;
			            vaDownRowChild.push(voChildInfo);
			            
			        } else if (voChildConst.rowIndex === vnRowIdx) {
			            voChildInfo["colIndex"] = voChildConst["colIndex"];
			            voChildInfo["ctrl"] = ctrl;
			            voChildInfo["const"] = voChildConst;
			            vaCurrentRowChild.push(voChildInfo);
			        }
			    });
			    
			    vaCurrentRowChild.forEach(function(ctrlInfo) {
			        var voCtrlConst = ctrlInfo["const"];
			        voCtrlConst["rowIndex"] = voCtrlConst["rowIndex"] + 1;
			        vcGrpForm.replaceConstraint(ctrlInfo["ctrl"], voCtrlConst);
			    });
			    
			    vaDownRowChild.forEach(function(ctrlInfo) {
			        var voCtrlConst = ctrlInfo["const"];
			        voCtrlConst["rowIndex"] = voCtrlConst["rowIndex"] - 1;
			        vcGrpForm.replaceConstraint(ctrlInfo["ctrl"], voCtrlConst);
			    });
			}

			/**
			 * 게시판 상세 컨텐츠 컨트롤 생성
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 그룹 ID
			 * @param {Object} poConst constraint
			 * @param {Object} poParams param
			 * @return {Object} 생성된 컨트롤 및 constraint
			 */
			function createBoardCtrl(psGrpId, poConst, poParams) {
			    
			    /**@type cpr.controls.Container*/
			    var vcGrpForm = app.lookup(psGrpId);
			    
			    var voSortConst = sortObjectKey(poConst); // 저장용 실제 constraint           
			    // 화면을 그리는데 사용할 constraint
			    var voViewConst = {
			        rowIndex: poConst["rowIndex"],
			        rowSpan: poConst["rowSpan"],
			        colIndex: poConst["colIndex"],
			        colSpan: poConst["colSpan"]
			    };
			    
			    var vcTargetCtrl = vcGrpForm.getChildren().filter(function(ctrl) {
			        var voConst = vcGrpForm.getConstraint(ctrl);
			        if (voConst["horizontalAlign"]) {
			            delete voConst.horizontalAlign;
			            delete voConst.width;
			        }
			        return JSON.stringify(voViewConst) === JSON.stringify(voConst);
			    });
			    
			    var vsAttrColId, vsAttrInsertYn;
			    
			    if (!ValueUtil.isNull(poParams["NTABRD_COL_ESNTAL_ID"])) {
			        vsAttrColId = poParams["NTABRD_COL_ESNTAL_ID"];
			    } else {
			        vsAttrColId = vcTargetCtrl[0].userAttr("_colId");
			    }
			    
			    vsAttrInsertYn = vcTargetCtrl[0].userAttr("_insertYn");
			    
			    // label 컨트롤 반환
			    var vaTargetLabelCtrl = vcGrpForm.getChildren().filter(function(ctrl) {
			        var voConts = vcGrpForm.getConstraint(ctrl);
			        
			        if (voConts["rowIndex"] == poConst["rowIndex"] && voConts["colIndex"] == (Number(poConst["colIndex"]) - 1)) {
			            return ctrl;
			        }
			    });
			    
			    vcGrpForm.removeChild(vaTargetLabelCtrl[0], true); // label 컨트롤 제거
			    vcGrpForm.removeChild(vcTargetCtrl[0], true); // 입력 컨트롤 제거
			    
			    /* Label 컨트롤 삽입 */
			    var voLabelConst = {
			        "colIndex": Number(voSortConst["colIndex"]) - 1,
			        "rowIndex": voSortConst["rowIndex"]
			    }
			    
			    var vcLabelCtrl = new cpr.controls.Output("_optLabel" + poConst["rowIndex"] + poConst["colIndex"]);
			    vcLabelCtrl.value = poParams["NTABRD_COL_NM"];
			    
			    // 라벨 필수여부 체크
			    if (poParams["ESNTL_YN"] == "Y") {
			        vcLabelCtrl.style.setClasses(["label", "require"]);
			    } else {
			        vcLabelCtrl.style.setClasses(["label"]);
			    }
			    vcGrpForm.addChild(vcLabelCtrl, voLabelConst);
			    
			    /* Type 컨트롤 삽입 */
			    
			    // 사용자 정의 컨트롤 크기를 지정할 경우 저장 constraint
			    if (poParams["WDTH_MXMM_PLACEM_YN"] != "Y") {
			        voSortConst["horizontalAlign"] = "left";
			        voSortConst["width"] = poParams["WDTH_SZ"];
			    }
			    
			    var vcCtrl = null;
			    switch (poParams["NTABRD_COL_TYPE_NM"]) {
			        case "COMBO":
			            vcCtrl = new cpr.controls.ComboBox();
			            break;
			        case "LINKCOMBO":
			            vcCtrl = new cpr.controls.LinkedComboBox();
			            break;
			        case "CHECK":
			            vcCtrl = new cpr.controls.CheckBoxGroup();
			            break;
			        case "RADIO":
			            vcCtrl = new cpr.controls.RadioButton();
			            break;
			        default:
			            vcCtrl = new cpr.controls.InputBox();
			            break;
			    }
			    vcCtrl.fieldLabel = poParams["NTABRD_COL_NM"];
			    
			    // 마지막 컬럼에 삭제, 행이동 버튼 추가    
			    var vnLastColIdx = null;
			    
			    if (voSortConst["colIndex"] == 1) {
			        if (voSortConst["colSpan"] == 7) vnLastColIdx = 1;
			    } else if (voSortConst["colIndex"] == 3) {
			        if (voSortConst["colSpan"] == 5) vnLastColIdx = 3;
			    } else if (voSortConst["colIndex"] == 5) {
			        if (voSortConst["colSpan"] == 3) vnLastColIdx = 5;
			    } else {
			        vnLastColIdx = 7
			    }
			    
			    // 삽입할 컨트롤 그룹 생성
			    var vcCtrlGrp = new cpr.controls.Container("_settingGrp" + poConst["rowIndex"] + poConst["colIndex"]);
			    var xYLayout = new cpr.controls.layouts.XYLayout();
			    vcCtrlGrp.setLayout(xYLayout);
			    
			    // 신규추가인 경우 사용자 속성 추가
			    if (!ValueUtil.isNull(vsAttrColId)) {
			        vcCtrlGrp.userAttr("_colId", vsAttrColId);
			    }
			    
			    if (!ValueUtil.isNull(vsAttrInsertYn)) {
			        vcCtrlGrp.userAttr("_insertYn", vsAttrInsertYn);
			    }
			    
			    if (voSortConst["colIndex"] == vnLastColIdx) { // 마지막 컬럼
			        
			        var voXyConst = {};
			        // 사용자 정의 컨트롤 크기를 지정할 경우 view constraint
			        if (poParams["WDTH_MXMM_PLACEM_YN"] != "Y") {
			            voXyConst = {
			                "top": "0px",
			                "bottom": "0px",
			                "left": "0px",
			                "width": (Number(poParams["WDTH_SZ"]) + 27) + "px"
			            }
			        } else {
			            voXyConst = {
			                "top": "0px",
			                "right": "86px",
			                "bottom": "0px",
			                "left": "0px"
			            }
			        }
			        
			        (function(container) {
			            var vcSubGrp = new cpr.controls.Container("_lastGrp");
			            var xYLayout = new cpr.controls.layouts.XYLayout();
			            vcSubGrp.setLayout(xYLayout);
			            (function(container) {
			                container.addChild(vcCtrl, {
			                    "top": "0px",
			                    "right": "27px",
			                    "bottom": "0px",
			                    "left": "0px"
			                });
			                var vcBtnAdd = createOptionButton(psGrpId, "ADD");
			                container.addChild(vcBtnAdd, {
			                    "right": "0px",
			                    "width": "22px",
			                    "height": "22px",
			                    "top": "calc(50% - 11px)"
			                });
			            })(vcSubGrp);
			            container.addChild(vcSubGrp, voXyConst);
			            
			            var vcBtnDel = createOptionButton(psGrpId, "DELETE");
			            container.addChild(vcBtnDel, {
			                "right": "59px",
			                "width": "22px",
			                "height": "22px",
			                "top": "calc(50% - 11px)"
			            });
			            var vcBtnUp = createOptionButton(psGrpId, "UP");
			            container.addChild(vcBtnUp, {
			                "right": "32px",
			                "width": "22px",
			                "height": "22px",
			                "top": "calc(50% - 11px)"
			            });
			            var vcBtnDown = createOptionButton(psGrpId, "DOWN");
			            container.addChild(vcBtnDown, {
			                "right": "5px",
			                "width": "22px",
			                "height": "22px",
			                "top": "calc(50% - 11px)"
			            });
			        })(vcCtrlGrp);
			        
			    } else {
			        
			        // 사용자 정의 컨트롤 크기를 지정할 경우 view constraint
			        if (poParams["WDTH_MXMM_PLACEM_YN"] != "Y") {
			            voViewConst["horizontalAlign"] = "left";
			            voViewConst["width"] = Number(poParams["WDTH_SZ"]) + 32;
			        }
			        
			        (function(container) {
			            container.addChild(vcCtrl, {
			                "top": "0px",
			                "right": "32px",
			                "bottom": "0px",
			                "left": "0px"
			            });
			            var vcBtnAdd = createOptionButton(psGrpId, "ADD");
			            container.addChild(vcBtnAdd, {
			                "right": "5px",
			                "width": "22px",
			                "height": "22px",
			                "top": "calc(50% - 11px)"
			            });
			        })(vcCtrlGrp);
			    }
			    
			    vcGrpForm.addChild(vcCtrlGrp, voViewConst);
			    vcGrpForm.redraw();
			    
			    var returnObj = {
			        "ctrl": vcCtrlGrp,
			        "conts": voSortConst
			    };
			    
			    return returnObj;
			}
			/**
			 * 게시판 상세 컨텐츠 컨트롤 삽입
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 그룹 ID
			 * @param {Object} poConst constraint
			 * @param {Object} poParams param
			 */
			function insertBoardCtrl(psGrpId, poConst, poParams) {
			    
			    var voCreateInfo = createBoardCtrl(psGrpId, poConst, poParams);
			    var vcCtrlGrp = voCreateInfo["ctrl"];
			    var voSortConst = voCreateInfo["conts"];
			    var vnNtabrdTmptCd;
			    
			    // dsBoardCol에 컬럼 정보를 저장한다.
			    var voDsBoardCol = app.lookup("dsBoardColList");
			    voDsBoardCol.clearFilter();
			    
			    voDsBoardCol.setSort("NTABRD_COL_ESNTAL_ID");
			    
			    var vnRowCnt = voDsBoardCol.getRowCount();
			    var vnColId;
			    
			    // 실제 저장되는 NTABRD_COL_ESNTAL_ID가 아니며 화면에서 COL_ID에 따른 순서를 반환받는 용도로 사용
			    vnColId = "i" + (vnRowCnt + 1);
			    
			    // 객체 확인을 위한 사용자 속성 colId 삽입
			    vcCtrlGrp.userAttr("_colId", String(vnColId));
			    vcCtrlGrp.userAttr("_insertYn", "Y");
			    
			    // 템플릿 구분 코드 기본상세 1, 답글상세 2
			    if (psGrpId == "grpBoardDtl") {
			        vnNtabrdTmptCd = 1;
			    } else {
			        vnNtabrdTmptCd = 2;
			    }
			    
			    // 신규 컬럼 정보 삽입    
			    voDsBoardCol.addRowData({
			        "NTABRD_ESNTAL_NO": msBrdId,
			        "NTABRD_COL_ESNTAL_ID": vnColId,
			        "NTABRD_COL_NM": poParams["NTABRD_COL_NM"],
			        "NTABRD_COL_TYPE_NM": poParams["NTABRD_COL_TYPE_NM"],
			        "NTABRD_TMPT_SE_CD": vnNtabrdTmptCd,
			        "ESNTL_YN": poParams["ESNTL_YN"],
			        "CMMNS_CD_ID": poParams["CMMNS_CD_ID"],
			        "CMMNS_CD_NM": poParams["CMMNS_CD_NM"],
			        "WDTH_MXMM_PLACEM_YN": poParams["WDTH_MXMM_PLACEM_YN"],
			        "WDTH_SZ": poParams["WDTH_SZ"],
			        "COL_BASS_VALUE": poParams["COL_BASS_VALUE"],
			        "COL_PLACEM_INFO_CN": JSON.stringify(voSortConst)
			    });
			}

			/**
			 * 게시판 상세 컨텐츠 컨트롤 업데이트
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 그룹 ID
			 * @param {Object} poConst constraint
			 * @param {Object} poParams param
			 * @param {Number} pnColId 컬럼 ID
			 */
			function updateBoardCtrl(psGrpId, poConst, poParams, pnColId) {
			    
			    var voCreateInfo = createBoardCtrl(psGrpId, poConst, poParams);
			    var vcCtrlGrp = voCreateInfo["ctrl"];
			    var voSortConst = voCreateInfo["conts"];
			    
			    // dsBoardCol에 컬럼 정보를 저장한다.
			    var voDsBoardCol = app.lookup("dsBoardColList");
			    voDsBoardCol.clearFilter();
			    var vnRowIdx = voDsBoardCol.findFirstRow("NTABRD_COL_ESNTAL_ID =='" + pnColId + "'").getIndex();
			    
			    // 업데이트 컬럼 정보 수정
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "NTABRD_COL_NM", poParams["NTABRD_COL_NM"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "NTABRD_COL_TYPE_NM", poParams["NTABRD_COL_TYPE_NM"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "ESNTL_YN", poParams["ESNTL_YN"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "CMMNS_CD_ID", poParams["CMMNS_CD_ID"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "CMMNS_CD_NM", poParams["CMMNS_CD_NM"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "WDTH_MXMM_PLACEM_YN", poParams["WDTH_MXMM_PLACEM_YN"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "WDTH_SZ", poParams["WDTH_SZ"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "COL_BASS_VALUE", poParams["COL_BASS_VALUE"]);
			    util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "COL_PLACEM_INFO_CN", JSON.stringify(voSortConst));
			    
			    // 상세설정 컬럼 정보 변경시 목록설정 정보 변경
			    if (psGrpId == "grpBoardDtl") {
			        var vcGrdInsBrdList = app.lookup("grdInsertBoardList");
			        var vaGrdHdrColIdxs = vcGrdInsBrdList.header.getCellIndices();
			        var vnGrdHdrColLng = vaGrdHdrColIdxs.length;
			        
			        for (var i = 0; i < vnGrdHdrColLng; i++) {
			            var voInfo = {};
			            
			            var voCol = vcGrdInsBrdList.detail.getColumn(vaGrdHdrColIdxs[i]);
			            var vsColId = voCol.columnName;
			            
			            if (pnColId == vsColId) {
			                vcGrdInsBrdList.header.getColumn(vaGrdHdrColIdxs[i]).setText(poParams["NTABRD_COL_NM"]);
			            }
			            
			        }
			    }
			}

			//************************** 댓글 설정 Function **************************/

			/**
			 * 댓글설정 항목변경시 보여줄 view를 구성합니다.
			 * @param {Number} pnTextMaxCnt 입력제한 글자수
			 * @param {String} pnTmptSeCd 댓글정보 표시항목
			 */
			function setCmntDtl(pnTextMaxCnt, pnTmptSeCd) {
			    
			    if (!ValueUtil.isNull(pnTextMaxCnt)) {
			        app.lookup("optCmtInfo").value = pnTextMaxCnt + "자 이내로 입력하세요";
			    }
			    
			    var vcOptWri = app.lookup("optCmtWriNm");
			    if (pnTmptSeCd == 1) {
			        vcOptWri.value = "작성자\r\nYYYY-MM-DD";
			    } else if (pnTmptSeCd == 2) {
			        vcOptWri.value = "작성자";
			    } else if (pnTmptSeCd == 3) {
			        vcOptWri.value = "YYYY-MM-DD";
			    } else if (pnTmptSeCd == 4) {
			        vcOptWri.value = "YYYY-MM-DD\r\nhh:mm:ss";
			    } else {
			        vcOptWri.value = "작성자\r\nYYYY-MM-DD\r\nhh:mm:ss";
			    }
			    
			}

			//************************** 목록 설정 Function **************************/

			/**
			 * 목록설정 그리드의 기본 컬럼 인덱스를 구성합니다.
			 */
			function setDefaultColIdx() {
			    var vcGrdInsList = app.lookup("grdInsertBoardList");
			    var vnColCnt = vcGrdInsList.header.cellCount;
			    
			    for (var i = 0; i < vnColCnt; i++) {
			        var vnColIdx = vcGrdInsList.getColumnLayout().detail[i].cellIndex;
			        
			        // 체크박스 컬럼
			        if (vnColIdx == 0) maDefGrdCellIdx.push(vnColIdx);
			        
			        var voCol = vcGrdInsList.detail.getColumn(vnColIdx);
			        if (!voCol) continue;
			        
			        var vsColNm = voCol.columnName;
			        if (vsColNm == "BRD_SEQ" || vsColNm == "TIT" || vsColNm == "WRI_DT" || vsColNm == "WRI_NM" || vsColNm == "RDCNT") {
			            maDefGrdCellIdx.push(vnColIdx);
			        }
			    }
			}

			/**
			 * 목록설정시 그리드에 추가될 컬럼들을 셋팅합니다.
			 * @param {Number} pnColId 컬럼 Id
			 * @param {String} psColNm 컬럼명
			 */
			function createColList(pnColId, psColNm) {
			    
			    var vcGrpListCol = app.lookup("grpListCol");
			    
			    var vcBtn = new cpr.controls.Button("_colItem" + pnColId);
			    vcBtn.value = psColNm;
			    vcBtn.userAttr("_colId", String(pnColId));
			    vcBtn.addEventListener("click", addColBtnClick);
			    
			    var vnBtnWidth;
			    
			    if (psColNm.length < 10) {
			        vnBtnWidth = 100;
			    } else {
			        vnBtnWidth = psColNm.length * 10;
			    }
			    
			    var voConts = {
			        "width": vnBtnWidth + "px",
			        "height": "25px"
			    };
			    
			    if (msCrudType == "READ") {
			        vcBtn.enabled = false;
			    } else {
			        vcBtn.enabled = true;
			    }
			    vcGrpListCol.addChild(vcBtn, voConts);
			}

			/**
			 * 목록설정의 컬럼 버튼 클릭시 발생 이벤트
			 */
			function addColBtnClick( /* cpr.events.CMouseEvent */ e) {
			    
			    /**@type cpr.controls.Button*/
			    var vcTargetBtn = e.control;
			    var vnColId = vcTargetBtn.userAttr("_colId");
			    var vcGrdInsBoardList = app.lookup("grdInsertBoardList");
			    var vaGrdHdrColIdxs = vcGrdInsBoardList.header.getCellIndices();
			    var vnGrdHdrColLng = vaGrdHdrColIdxs.length;
			    
			    for (var i = vnGrdHdrColLng - 1; i >= 1; i--) {
			        var vsDrawColId = vcGrdInsBoardList.detail.getColumn(vaGrdHdrColIdxs[i]);
			        if (!vsDrawColId) continue;
			        
			        var vsAddColId = vsDrawColId.columnName;
			        
			        // 이미 컬럼이 추가되어 있으면 제거
			        if (vsAddColId == vnColId) {
			            vcGrdInsBoardList.deleteColumn(vaGrdHdrColIdxs[i]);
			            
			            return false;
			        }
			    }
			    
			    var voDsBrdCol = app.lookup("dsBoardColList");
			    var vnRowIdx = voDsBrdCol.findFirstRow("NTABRD_COL_ESNTAL_ID =='" + vnColId + "'").getIndex();
			    
			    var vsColNm = util.DataSet.getValue(app, "dsBoardColList", vnRowIdx, "NTABRD_COL_NM");
			    var vsColId = util.DataSet.getValue(app, "dsBoardColList", vnRowIdx, "NTABRD_COL_ESNTAL_ID");
			    var vnColWidth = app.lookup("nbeColWidth").value;
			    
			    addGridColumn(vsColId, vsColNm, vnColWidth);
			    
			}

			/**
			 * 목록설정 그리드에 컬럼을 추가합니다.
			 * @param {String} psColId
			 * @param {String} psColNm
			 * @param {Number} pnWidth
			 */
			function addGridColumn(psColId, psColNm, pnWidth) {
			    var vcGrdInsBoardList = app.lookup("grdInsertBoardList");
			    var vaGrdHdrColIdxs = vcGrdInsBoardList.header.getCellIndices();
			    var vnGrdHdrColLng = vaGrdHdrColIdxs.length;
			    
			    vcGrdInsBoardList.addColumn({
			        columnLayout: [{
			            width: pnWidth + "px"
			        }],
			        header: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: vnGrdHdrColLng
			            },
			            configurator: function(cell) {
			                cell.targetColumnName = psColId;
			                cell.text = psColNm;
			            }
			        }],
			        detail: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: vnGrdHdrColLng
			            },
			            configurator: function(cell) {
			                cell.columnName = psColId;
			            }
			        }]
			    });
			    
			    // 등록일 컬럼 앞으로 추가된 컬럼 이동
			    var vnCellIdx = vcGrdInsBoardList.getCellIndex(psColId);
			    vcGrdInsBoardList.moveColumn(vnCellIdx, 3, true);
			}

			/**
			 * 목록설정 데이터를 데이터 셋에 저장 합니다.
			 */
			function setBoardColListInfo() {
			    
			    var vcGrdInsBrdList = app.lookup("grdInsertBoardList");
			    var voDsBrdCol = app.lookup("dsBoardColList");
			    var vnDsRowCnt = voDsBrdCol.getRowCount();
			    
			    // 저장전 기본 목록 정보 초기화
			    for (var idx = 0; idx < vnDsRowCnt; idx++) {
			        
			        voDsBrdCol.setValue(idx, "LIST_CONTRO_SIZEA_SZ", null);
			        voDsBrdCol.setValue(idx, "NTABRD_COL_SRTNG_SQNCE", null);
			        
			    }
			    
			    var voGrdInsColLot = vcGrdInsBrdList.getColumnLayout();
			    var vaGrdHdrColIdxs = vcGrdInsBrdList.header.getCellIndices();
			    var vnGrdHdrColLng = vaGrdHdrColIdxs.length;
			    
			    for (var i = vnGrdHdrColLng - 1; i >= 1; i--) {
			        var voCol = vcGrdInsBrdList.detail.getColumn(vaGrdHdrColIdxs[i]);
			        var vsColId = voCol.columnName;
			        var vnCellIdx = voCol.cellIndex;
			        
			        if (!vsColId) continue;
			        // 기본 컬럼 제외
			        if (maDefGrdCellIdx.indexOf(vnCellIdx) != -1) continue;
			        
			        var vnRowIdx = voDsBrdCol.findFirstRow("NTABRD_COL_ESNTAL_ID == '" + vsColId + "'").getIndex();
			        var vnColIdx = voCol.colIndex;
			        
			        var vnListColSize = voGrdInsColLot.columnLayout[vnColIdx].width;
			        var vnListOrder = vnColIdx - 2;
			        
			        voDsBrdCol.setValue(vnRowIdx, "LIST_CONTRO_SIZEA_SZ", vnListColSize);
			        voDsBrdCol.setValue(vnRowIdx, "NTABRD_COL_SRTNG_SQNCE", vnListOrder);
			        
			    }
			    
			}

			/**
			 * 목록설정시 그리드 컬럼 추가를 위한 버튼을 생성합니다.
			 */
			function setColList() {
			    
			    var voDsBrdCol = app.lookup("dsBoardColList");
			    //    voDsBrdCol.setFilter("NTABRD_TMPT_SE_CD == 1");
			    voDsBrdCol.clearFilter();
			    
			    if (voDsBrdCol.getRowCount() == 0) return;
			    
			    var voTargetFindRows = voDsBrdCol.findAllRow("NTABRD_ESNTAL_NO =='" + msBrdId + "'");
			    
			    voTargetFindRows.forEach(function(row) {
			        var vsStrRowState = row.getStateString();
			        
			        // 삭제된 데이터 추가 x
			        if (vsStrRowState == "D" || vsStrRowState == "ID") return false;
			        
			        var vnRowIdx = row.getIndex();
			        var vnColId = util.DataSet.getValue(app, "dsBoardColList", vnRowIdx, "NTABRD_COL_ESNTAL_ID");
			        var vsColNm = util.DataSet.getValue(app, "dsBoardColList", vnRowIdx, "NTABRD_COL_NM");
			        
			        createColList(vnColId, vsColNm);
			    });
			}

			//************************** 유효성 체크 Function **************************/

			/**
			 * 상세설정에서 변경된 constraint 데이터 셋 업데이트
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 그룹 ID
			 */
			function updateBoardFormColInfo(psGrpId) {
			    
			    var voDsBrdCol = app.lookup("dsBoardColList");
			    var vcGrpBrdForm = app.lookup(psGrpId);
			    
			    vcGrpBrdForm.getChildren().forEach(function(ctrl) {
			        var pnColId = ctrl.userAttr("_colId");
			        
			        if (!ValueUtil.isNull(pnColId)) {
			            
			            var voSortConst = vcGrpBrdForm.getConstraint(ctrl);
			            var voJsonConst = JSON.stringify(voSortConst);
			            var vnRowIdx = voDsBrdCol.findFirstRow("NTABRD_COL_ESNTAL_ID =='" + pnColId + "'").getIndex();
			            var voConst = util.DataSet.getValue(app, "dsBoardColList", vnRowIdx, "COL_PLACEM_INFO_CN");
			            
			            if (voJsonConst !== voConst) {
			                
			                util.DataSet.setValue(app, "dsBoardColList", vnRowIdx, "COL_PLACEM_INFO_CN", JSON.stringify(voSortConst));
			            }
			        }
			    });
			}

			/**
			 * 상세설정, 답글설정에서 적용하지 않은 컨트롤이 있는지 체크합니다.
			 * @param {"grpBoardDtl" | "grpBoardReply"} psGrpId 그룹 ID
			 */
			function checkBrdFormBeforeCol(psGrpId) {
			    
			    var vsTargetGrp;
			    
			    if (psGrpId == "grpBoardDtl") {
			        vsTargetGrp = "상세설정";
			    } else {
			        vsTargetGrp = "답글설정";
			    }
			    
			    var vcGrpBrdForm = app.lookup(psGrpId);
			    var vbValidate = true;
			    var vaChildCtrl = vcGrpBrdForm.getChildren();
			    
			    vaChildCtrl.sort(function(a, b) {
			        var vnARowIdx = vcGrpBrdForm.getConstraint(a).rowIndex;
			        var vnBRowIdx = vcGrpBrdForm.getConstraint(b).rowIndex;
			        return vnARowIdx - vnBRowIdx;
			    });
			    
			    vaChildCtrl.some(function(ctrl) {
			        
			        if (ctrl.id.indexOf("_beforeGrp") != -1) {
			            vbValidate = false;
			            var voChildConts = vcGrpBrdForm.getConstraint(ctrl);
			            var vnRowIdx = voChildConts.rowIndex;
			            var vnColIdx = voChildConts.colIndex + 1;
			            
			            util.Msg.alert(app, vsTargetGrp + "에 설정되지 않은 컨트롤이 있습니다.");
			        }
			        
			        return ctrl.id.indexOf("_beforeGrp") != -1;
			    });
			    
			    if (vbValidate) {
			        return true;
			    } else {
			        return false;
			    }
			}

			/**
			 * 게시판 컬럼 설정시 변경사항을 체크합니다.
			 * @return {Object} modified 정보(Key : isModified, modifiedStep)
			 */
			function checkIsModified() {
			    
			    var voDsBrdList = app.lookup("dsBoardList");
			    var voDsBrdColList = app.lookup("dsBoardColList");
			    voDsBrdColList.clearFilter();
			    
			    var vcGrdInsBrdList = app.lookup("grdInsertBoardList");
			    
			    var vaBeforeColInfo = [];
			    var vaAfterColInfo = [];
			    
			    /* 목록설정 modified 체크 구성*/
			    for (var i = 0; i < voDsBrdColList.getRowCount(); i++) {
			        var voInfo = {};
			        
			        var vnListOrder = voDsBrdColList.getValue(i, "NTABRD_COL_SRTNG_SQNCE");
			        if (!ValueUtil.isNull(vnListOrder)) {
			            voInfo["NTABRD_COL_ESNTAL_ID"] = voDsBrdColList.getValue(i, "NTABRD_COL_ESNTAL_ID");
			            voInfo["NTABRD_COL_NM"] = voDsBrdColList.getValue(i, "NTABRD_COL_NM");
			            voInfo["NTABRD_COL_SRTNG_SQNCE"] = voDsBrdColList.getValue(i, "NTABRD_COL_SRTNG_SQNCE");
			            voInfo["LIST_CONTRO_SIZEA_SZ"] = voDsBrdColList.getValue(i, "LIST_CONTRO_SIZEA_SZ");
			            
			            vaBeforeColInfo.push(voInfo);
			        }
			    }
			    
			    vaBeforeColInfo.sort(function(a, b) {
			        return a["NTABRD_COL_SRTNG_SQNCE"] - b["NTABRD_COL_SRTNG_SQNCE"]
			    });
			    
			    var voGrdInsColLot = vcGrdInsBrdList.getColumnLayout();
			    var vaGrdHdrColIdxs = vcGrdInsBrdList.header.getCellIndices();
			    var vnGrdHdrColLng = vaGrdHdrColIdxs.length;
			    
			    for (var i = 0; i < vnGrdHdrColLng; i++) {
			        var voInfo = {};
			        
			        var voCol = vcGrdInsBrdList.detail.getColumn(vaGrdHdrColIdxs[i]);
			        var vsColId = voCol.columnName;
			        
			        if (!vsColId) continue;
			        
			        // 기본 컬럼 제외        
			        if (maDefGrdCellIdx.indexOf(voCol.cellIndex) != -1) continue;
			        
			        var vnColIdx = voCol.colIndex;
			        
			        voInfo["NTABRD_COL_ESNTAL_ID"] = voCol.columnName;
			        voInfo["NTABRD_COL_NM"] = vcGrdInsBrdList.header.getColumn(vaGrdHdrColIdxs[i]).getText();
			        voInfo["NTABRD_COL_SRTNG_SQNCE"] = vnColIdx - 2;
			        voInfo["LIST_CONTRO_SIZEA_SZ"] = voGrdInsColLot.columnLayout[vnColIdx].width;
			        
			        vaAfterColInfo.push(voInfo);
			    }
			    
			    // 데이터 변경사항이 없을시 "변경된 데이터가 없습니다" 출력
			    var vcStepProgs = app.lookup("cmnStepProgress");
			    
			    if (voDsBrdList.getRowStatedIndices(cpr.data.tabledata.RowState.UPDATED | cpr.data.tabledata.RowState.INSERTED).length > 0) {
			        
			        if (!mbCmntModified) {
			            return {
			                isModified: true,
			                modifiedStep: vcStepProgs.getStepInfo(1)["stepValue"]
			            };
			        } else { // 댓글설정 변경사항 체크
			            return {
			                isModified: true,
			                modifiedStep: vcStepProgs.getStepInfo(3)["stepValue"]
			            };
			        }
			        
			    } else if (voDsBrdColList.isModified()) {
			        
			        var vaRowIdx = voDsBrdColList.getRowStatedIndices(cpr.data.tabledata.RowState.UPDATED | cpr.data.tabledata.RowState.INSERTED | cpr.data.tabledata.RowState.DELETED);
			        
			        for (var i = 0; i < vaRowIdx.length; i++) {
			            var vsNtabrdTmptCd = voDsBrdColList.getRow(vaRowIdx[i]).getValue("NTABRD_TMPT_SE_CD");
			            
			            if (vsNtabrdTmptCd == "1") {
			                return {
			                    isModified: true,
			                    modifiedStep: vcStepProgs.getStepInfo(2)["stepValue"]
			                };
			            } else if (vsNtabrdTmptCd == "2") { // 답글설정 변경사항 체크               
			                return {
			                    isModified: true,
			                    modifiedStep: vcStepProgs.getStepInfo(3)["stepValue"]
			                };
			            }
			            
			            break;
			        }
			        
			    } else if (JSON.stringify(vaBeforeColInfo) != JSON.stringify(vaAfterColInfo) && !mbIgnoreModified) { // 목록설정
			        
			        return {
			            isModified: true,
			            modifiedStep: vcStepProgs.getStepInfo(maStepToTabId.length)["stepValue"]
			        };
			        
			    } else {
			        return {
			            isModified: false,
			            modifiedStep: ""
			        };
			    }
			}

