			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick( /* cpr.events.CMouseEvent */ e) {
			    /** 
			     * @type cpr.controls.Button
			     */
			    var btnSave = e.control;
			    
			    // 상세설정 빈 컬럼 체크
			    if (!checkBrdFormBeforeCol("grpBoardDtl")) return;
			    
			    // 답글설정 빈 컬럼 체크
			    if (msSelectBrdType == "2") {
			        if (!checkBrdFormBeforeCol("grpBoardReply")) return;
			    }
			    
			    // 상세설정에서 변경된 constraint 데이터 셋 업데이트 
			    updateBoardFormColInfo("grpBoardDtl");
			    
			    if (msSelectBrdType == "2") {
			        // 답글성정에서 변경된 constraint 데이터 셋 업데이트
			        updateBoardFormColInfo("grpBoardReply");
			    }
			    
			    // 게시판을 등록할 프로그램 정보를 셋팅합니다.
			    updateProgramInfo();
			    
			    if (!checkIsModified().isModified) {
			        
			        util.Msg.alert(app, "INF-M006");
			    } else {
			        setBoardColListInfo();
			        mbIgnoreModified = true;
			        
			        doSave();
			    }
			}

			/************************** 게시판 목록(게시판 변경시) Event **************************/

			/*
			 * 그리드에서 before-selection-change 이벤트 발생 시 호출.
			 * detail의 cell 클릭하여 설정된 selectionunit에 해당되는 단위가 선택되기 전에 발생하는 이벤트.
			 */
			function onGrdBoardListBeforeSelectionChange( /* cpr.events.CSelectionEvent */ e) {
			    /** 
			     * @type cpr.controls.Grid
			     */
			    var grdBoardList = e.control;
			    
			    if (e.oldSelection.length < 1) return;
			    
			    var vnOldRowState = util.Grid.getRowState(app, "grdBoardList", e.oldSelection[0]);
			    var vnNewRowState = util.Grid.getRowState(app, "grdBoardList", e.newSelection[0]);
			    
			    // 변경되지 않은 상태(1), 행이 신규로 추가된 상태 (2) RowState 참고
			    if (vnOldRowState == 2) {
			        e.preventDefault();
			        util.Msg.alert(app, "현재 신규 작성중인 게시판이 있습니다.");
			        
			    } else {
			        
			        if (!mbSucessSelect) {
			            var voModified = checkIsModified();
			            
			            if (voModified.isModified) {
			                e.preventDefault();
			                
			                util.Msg.confirm(app, "CRM-M003", voModified.modifiedStep, function() {
			                    mbSucessSelect = true;
			                    
			                    util.DataSet.revertRow(app, "dsBoardList", e.oldSelection[0]);
			                    app.lookup("grdBoardList").selectRows(e.newSelection[0]);
			                    
			                });
			            }
			        }
			    }
			}

			/*
			 * 그리드에서 selection-change 이벤트 발생 시 호출.
			 * detail의 cell 클릭하여 설정된 selectionunit에 해당되는 단위가 선택될 때 발생하는 이벤트.
			 */
