			    var vnRowIdx = util.Grid.getIndex(app, "grdBoardList");
			    
			    // 기본 데이터 입력
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "UNT_TASKWK_SE_CD", msBeforeSysCd);
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "NTABRD_TYPE_SE_CD", "1");
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "BBSCTT_RLS_TYPE_NM", "1");
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "IMPRTN_NTC_YN", "Y");
			    //20230719_강화영_데이터정합성이슈로 수정
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "USE_YN", "Y");
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "RDCNT_INDCT_YN", "Y");
			    util.DataSet.setValue(app, "dsBoardList", vnRowIdx, "ATCMFL_SIZEA_MXMM_SZ", "100");
			    
