			/**
			 * 선택한 추가 컬럼 갯수에 따라 배치구성 콤보를 필터합니다.(상세설정, 답글설정)
			 * @param {#uicontrol} psCtrlId 배치구성 콤보 아이디
			 * @param {Number} pnNbeVal 추가 컬럼 갯수
			 */
			function setFilterColBat(psCtrlId, pnNbeVal) {
			    
			    /**@type cpr.controls.ComboBox*/
			    var vcCmbColBat = app.lookup(psCtrlId);
			    
			    if (pnNbeVal == "1" || pnNbeVal == "4") {
			        if (pnNbeVal == "1") {
			            vcCmbColBat.setFilter("value == 1");
			        } else {
			            vcCmbColBat.setFilter("value == 8");
			        }
			        vcCmbColBat.enabled = false;
			        vcCmbColBat.selectItem(0);
			        
			    } else {
			        
			        if (pnNbeVal == "2") {
			            vcCmbColBat.setFilter("value > 1 && value < 5");
			        } else {
			            vcCmbColBat.setFilter("value > 4 && value < 8");
			        }
			        vcCmbColBat.enabled = true;
			        vcCmbColBat.selectItem(0);
			    }
			}

