			/*
			 * 그리드에서 before-cell-moved 이벤트 발생 시 호출.
			 * Grid의 Cell을 이동하기 전에 발생하는 이벤트.
			 */
			function onGrdInsertBoardListBeforeCellMoved( /* cpr.events.CGridEvent */ e) {
			    /** 
			     * @type cpr.controls.Grid
			     */
			    var vcGrdInsList = e.control;
			    var vnSourceHdrIdx = e.data.sourceHeaderIndex;
			    var vnTargetHdrIdx = e.data.targetHeaderIndex;
			    var vbMoveBefore = e.data.before;
			    
			    // 기본 컬럼 위치 변경 불가 적용
			    maDefGrdCellIdx.forEach(function(idx) {
			        if (idx == vnSourceHdrIdx) {
			            e.preventDefault();
			        }
			    });
			    
			    if (maDefGrdCellIdx[0] == vnTargetHdrIdx || maDefGrdCellIdx[1] == vnTargetHdrIdx || maDefGrdCellIdx[4] == vnTargetHdrIdx || maDefGrdCellIdx[5] == vnTargetHdrIdx) {
			        e.preventDefault();
			    } else if (maDefGrdCellIdx[2] == vnTargetHdrIdx && vbMoveBefore) {
			        e.preventDefault();
			    } else if (maDefGrdCellIdx[3] == vnTargetHdrIdx && !vbMoveBefore) {
			        e.preventDefault();
			    }
			    
			}

